AGES = (("0-30", 30), ("31-60", 60), ("61-90", 90), ("90+", None))


def aging(journal, today, code="1100"):
    """`code`'s open debits by age on `today` (days since the entry): rows
    of (bucket, cents), every bucket, the credits paying the oldest debits
    first."""
    debits, paid = [], 0
    for entry, line in journal.lines(code):
        if line.cents > 0:
            debits.append([entry.date, line.cents])
        else:
            paid -= line.cents
    for debit in debits:
        take = min(paid, debit[1])
        debit[1] -= take
        paid -= take
    out = {name: 0 for name, _ in AGES}
    for date, cents in debits:
        days = (today - date).days
        name = next(n for n, top in AGES if top is None or days <= top)
        out[name] += cents
    return list(out.items())


